selector_to_html = {"a[href=\"BladeSettings.html#pyskyfire.pump.geometry.BladeSettings\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.geometry.BladeSettings\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">BladeSettings</span></span></dt><dd><p>Blade extent in normalized hub arc length and edge construction controls.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">start</span></code> is the leading edge. One station puts it on an existing span line;\na <code class=\"docutils literal notranslate\"><span class=\"pre\">(hub,</span> <span class=\"pre\">tip)</span></code> pair slants it, beginning the blade further downstream on\nthe hub as a blade development normally is drawn, and the passage is\nre-paired to carry that line. Both stations are always available as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">start_hub</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">start_tip</span></code>.</p><p>Thickness is a body thickness; both edges close to a point. The leading\nedge is rounded by pyTurbo. <code class=\"docutils literal notranslate\"><span class=\"pre\">trailing_edge</span></code> selects its closure style.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">angle_law</span></code> is used only to estimate total wrap.</p></dd>", "a[href=\"SplitterSettings.html#pyskyfire.pump.geometry.SplitterSettings\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.geometry.SplitterSettings\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SplitterSettings</span></span></dt><dd><p>One repeated splitter family following the main-blade camber.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">start</span></code> is the fraction of the main camber parameter where it begins;\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pitch_fraction</span></code> locates it between adjacent main blades.</p></dd>", "a[href=\"ImpellerBladeDefinition.html#pyskyfire.pump.geometry.ImpellerBladeDefinition\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.geometry.ImpellerBladeDefinition\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpellerBladeDefinition</span></span></dt><dd></dd>", "a[href=\"ImpellerGeometry.html#pyskyfire.pump.geometry.ImpellerGeometry\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.geometry.ImpellerGeometry\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpellerGeometry</span></span></dt><dd></dd>", "a[href=\"BladeSection.html#pyskyfire.pump.geometry.BladeSection\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.geometry.BladeSection\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">BladeSection</span></span></dt><dd></dd>", "a[href=\"MeridionalContours.html#pyskyfire.pump.geometry.MeridionalContours\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.geometry.MeridionalContours\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">MeridionalContours</span></span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../../common/meridional/MeridionalPassage.html#pyskyfire.common.meridional.MeridionalPassage\" title=\"pyskyfire.common.meridional.MeridionalPassage\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.common.meridional.MeridionalPassage</span></code></a></p><p>A radial impeller\u2019s passage: axial inlet, radial outlet, in (x,r) metres.</p><p>The shared <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">MeridionalPassage</span></code> with the checks\nonly a radial wheel satisfies: both walls rise monotonically in x and r,\nand the hub runs axially downstream of the shroud.</p></dd>", "a[href=\"#module-pyskyfire.pump.geometry\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.pump.geometry<a class=\"headerlink\" href=\"#module-pyskyfire.pump.geometry\" title=\"Link to this heading\">\u00b6</a></h1><p>Pump geometry contracts. Lengths are metres; cylindrical arrays are (x,r,theta).</p><p>The shaft is +x, and which way it turns about that axis is named by the\nimpeller\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">rotation</span></code>: counterclockwise means the right-handed sense about\n+x, seen with the axis pointing at the viewer. A backward-swept blade has\ndecreasing theta from leading to trailing edge in that sense, and a clockwise\nimpeller is its mirror image, built by negating theta.</p>", "a[href=\"../../common/rotation/index.html#module-pyskyfire.common.rotation\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.rotation<a class=\"headerlink\" href=\"#module-pyskyfire.common.rotation\" title=\"Link to this heading\">\u00b6</a></h1><p>Sense of rotation about a component\u2019s own axis.</p><p>An impeller spins one way about its shaft and the volute around it must wind\nthe same way, since a volute wound against the discharge swirl collects the\nflow backwards. Both state the sense with the same word here, so that a design\ncan be checked by reading it rather than by looking at a render.</p>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
